//! End-to-end CLI coverage for the MDX import, lookup, search and export
//! pipeline, using synthetic fixtures generated by odc-testkit.

use assert_cmd::Command;
use predicates::prelude::*;
use serde_json::Value;
use std::fs;
use std::path::{Path, PathBuf};
use tempfile::TempDir;

const ENTRIES: [(&str, &str); 4] = [
    ("alpha", "<p>alpha body</p>"),
    ("Bravo", "<p>bravo body</p>"),
    ("bravo", "<p>second bravo body</p>"),
    ("charlie", "<p>charlie body</p>"),
];

fn odc(dir: &Path) -> Command {
    let mut command = Command::cargo_bin("odc").expect("odc binary");
    command.arg("--repo").arg(dir);
    command
}

fn stdout_of(command: &mut Command) -> String {
    let output = command.output().expect("run odc");
    assert!(
        output.status.success(),
        "stderr: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8_lossy(&output.stdout).into_owned()
}

fn fixture(dir: &Path, version: u8) -> PathBuf {
    let path = dir.join(format!("fixture-v{version}.mdx"));
    match version {
        1 => odc_testkit::write_v1_mdx(&path, &ENTRIES).expect("v1 fixture"),
        2 => odc_testkit::write_v2_mdx(&path, &ENTRIES).expect("v2 fixture"),
        other => panic!("unsupported fixture version {other}"),
    }
    path
}

fn build_repo(dir: &Path, version: u8) {
    let temp = TempDir::new().expect("tempdir");
    let mdx = fixture(temp.path(), version);
    stdout_of(odc(dir).arg("init"));
    let output = stdout_of(odc(dir).arg("import").arg(&mdx).arg("--format").arg("mdx"));
    assert!(output.contains("working set = 4"), "{output}");
    assert!(output.contains("1 duplicate keys suffixed"), "{output}");
    stdout_of(odc(dir).arg("commit").args([
        "-m",
        "mdx import",
        "--author",
        "test",
        "--timestamp",
        "1700000000",
    ]));
}

#[test]
fn mdx_import_commits_and_reports_counts() {
    let repo = TempDir::new().expect("tempdir");
    build_repo(repo.path(), 1);

    let status = stdout_of(odc(repo.path()).arg("status"));
    assert!(status.contains("working set clean (4 entries)"), "{status}");
    assert!(status.contains("index: 4 entries, 1 blocks"), "{status}");

    let verify = stdout_of(odc(repo.path()).arg("verify"));
    assert!(verify.contains("verify: OK"), "{verify}");
}

#[test]
fn version_2_fixtures_import_the_same_way() {
    let repo = TempDir::new().expect("tempdir");
    build_repo(repo.path(), 2);
    let status = stdout_of(odc(repo.path()).arg("status"));
    assert!(status.contains("index: 4 entries"), "{status}");
}

#[test]
fn lookup_returns_payload_and_exit_code_four_when_missing() {
    let repo = TempDir::new().expect("tempdir");
    build_repo(repo.path(), 1);

    let json = stdout_of(odc(repo.path()).args(["lookup", "Alpha", "--json"]));
    let value: Value = serde_json::from_str(&json).expect("json");
    assert_eq!(value["word"], "alpha");
    assert_eq!(value["display"], "alpha");
    assert_eq!(value["raw_html"], "<p>alpha body</p>");

    let suffixed = stdout_of(odc(repo.path()).args(["lookup", "BRAVO", "--json"]));
    let value: Value = serde_json::from_str(&suffixed).expect("json");
    assert_eq!(value["word"], "bravo");

    odc(repo.path())
        .args(["lookup", "delta"])
        .assert()
        .code(4)
        .stderr(predicate::str::contains("not found: delta"));
}

#[test]
fn search_lists_prefix_matches_in_key_order() {
    let repo = TempDir::new().expect("tempdir");
    build_repo(repo.path(), 1);

    let output =
        stdout_of(odc(repo.path()).args(["search", "--prefix", "Bra", "--limit", "10", "--json"]));
    let rows: Vec<Value> = serde_json::from_str(&output).expect("json");
    assert_eq!(rows.len(), 2, "{output}");
    assert_eq!(rows[0]["word"], "bravo");
    assert_eq!(rows[0]["display"], "Bravo");
    assert_eq!(rows[1]["display"], "bravo");

    let text = stdout_of(odc(repo.path()).args(["search", "--prefix", "cha"]));
    assert_eq!(text.trim(), "charlie");
}

#[test]
fn jsonl_export_round_trips_into_a_fresh_repository() {
    let source = TempDir::new().expect("tempdir");
    build_repo(source.path(), 1);
    let export = source.path().join("dump.jsonl");
    stdout_of(
        odc(source.path())
            .args(["export", "--format", "jsonl", "-o"])
            .arg(&export),
    );
    let contents = fs::read_to_string(&export).expect("read export");
    let lines: Vec<&str> = contents
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect();
    assert_eq!(lines.len(), 4);

    let target = TempDir::new().expect("tempdir");
    stdout_of(odc(target.path()).arg("init"));
    let imported = stdout_of(
        odc(target.path())
            .arg("import")
            .arg(&export)
            .args(["--format", "jsonl"]),
    );
    assert!(imported.contains("working set = 4"), "{imported}");
    stdout_of(odc(target.path()).arg("commit").args([
        "-m",
        "roundtrip",
        "--author",
        "test",
        "--timestamp",
        "1700000001",
    ]));

    let left = stdout_of(odc(source.path()).args(["lookup", "alpha", "--json"]));
    let right = stdout_of(odc(target.path()).args(["lookup", "alpha", "--json"]));
    assert_eq!(left, right);

    let status = stdout_of(odc(target.path()).arg("status"));
    assert!(status.contains("index: 4 entries, 1 blocks"), "{status}");
}

#[test]
fn csv_export_keeps_raw_html_and_can_be_reimported() {
    let repo = TempDir::new().expect("tempdir");
    build_repo(repo.path(), 2);
    let export = repo.path().join("dump.csv");
    stdout_of(
        odc(repo.path())
            .args(["export", "--format", "csv", "-o"])
            .arg(&export),
    );
    let text = fs::read_to_string(&export).expect("read csv");
    assert!(
        text.starts_with("word,display,pos,sense,raw_html"),
        "{text}"
    );
    assert_eq!(text.lines().count(), 5);

    let target = TempDir::new().expect("tempdir");
    stdout_of(odc(target.path()).arg("init"));
    let imported = stdout_of(
        odc(target.path())
            .arg("import")
            .arg(&export)
            .args(["--format", "csv"]),
    );
    assert!(imported.contains("working set = 4"), "{imported}");
    stdout_of(odc(target.path()).arg("commit").args([
        "-m",
        "csv roundtrip",
        "--author",
        "test",
        "--timestamp",
        "1700000002",
    ]));
    let json = stdout_of(odc(target.path()).args(["lookup", "charlie", "--json"]));
    let value: Value = serde_json::from_str(&json).expect("json");
    assert_eq!(value["raw_html"], "<p>charlie body</p>");
}

#[test]
fn limit_caps_the_number_of_imported_entries() {
    let temp = TempDir::new().expect("tempdir");
    let mdx = fixture(temp.path(), 1);
    let repo = TempDir::new().expect("tempdir");
    stdout_of(odc(repo.path()).arg("init"));
    let output = stdout_of(
        odc(repo.path())
            .arg("import")
            .arg(&mdx)
            .args(["--format", "mdx", "--limit", "2"]),
    );
    assert!(output.contains("working set = 2"), "{output}");
}

/// Digits immediately following `marker` (skipping spaces).
fn number_after(output: &str, marker: &str) -> usize {
    let start = output
        .find(marker)
        .unwrap_or_else(|| panic!("missing {marker} in {output}"))
        + marker.len();
    let digits: String = output[start..]
        .trim_start()
        .chars()
        .take_while(char::is_ascii_digit)
        .collect();
    digits.parse().expect("a number after the marker")
}

#[test]
fn corrupt_version_2_blocks_are_skipped_and_reported() {
    let repo_dir = TempDir::new().expect("tempdir");
    let input_dir = TempDir::new().expect("tempdir");
    let entries: Vec<(String, String)> = (0..60)
        .map(|index| {
            (
                format!("word{index:04}"),
                format!("<p>{index}</p>{}", "x".repeat(8 * 1024)),
            )
        })
        .collect();
    let rows: Vec<(&str, &str)> = entries
        .iter()
        .map(|(key, body)| (key.as_str(), body.as_str()))
        .collect();
    let mdx = input_dir.path().join("big-v2.mdx");
    odc_testkit::write_v2_mdx(&mdx, &rows).expect("write fixture");

    // Damage the last record block by flipping a byte in its payload.
    let mut bytes = fs::read(&mdx).expect("read fixture");
    let last = bytes.len() - 10;
    bytes[last] ^= 0xff;
    fs::write(&mdx, &bytes).expect("write corrupt fixture");

    stdout_of(odc(repo_dir.path()).arg("init"));
    let output = stdout_of(
        odc(repo_dir.path())
            .arg("import")
            .arg(&mdx)
            .arg("--format")
            .arg("mdx"),
    );
    assert!(
        output.contains("mdx: skipped 1 corrupt record block"),
        "{output}"
    );
    let imported = number_after(&output, "imported ");
    let skipped = number_after(&output, "corrupt record block (");
    assert_eq!(imported + skipped, entries.len(), "{output}");
    assert!(skipped > 0 && skipped < entries.len(), "{output}");
    let status = stdout_of(odc(repo_dir.path()).arg("status"));
    assert!(
        status.contains(&format!("working set: {imported} entries")),
        "{status}"
    );
}
